bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || exit 61
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {createTelegramVideoFetcher} from './src/telegram/telegramFileFetch.mjs';
import {createStickerPaidCover} from './src/stickers/stickerPaidCover.mjs';
setDefaultResultOrder('ipv4first');setDefaultAutoSelectFamily(false);
const e=process.env,pid='sp_76f23430d1c29ca355960a95';
const chatId=-1002373696859,threadId=4640,oldId=4663;
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,
 database:e.VIDEOBOT_DB_NAME,password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),
 max:2,connectionTimeoutMillis:5000});
const outgoing=createCreatorTelegramFetch(globalThis.fetch);
try{
 const q=await pool.query("SELECT p.*,t.status AS post_status,t.chat_id,t.message_thread_id,t.telegram_message_id FROM videobot_sticker_products p JOIN videobot_sticker_topic_posts t ON t.product_id=p.product_id WHERE p.product_id=$1",[pid]);
 if(q.rowCount!==1)throw Error('STK_REPAIR_PRODUCT_NOT_UNIQUE');
 const p=q.rows[0];
 if(p.status!=='published'||p.post_status!=='sent'||
   Number(p.price_stars)!==50||Number(p.chat_id)!==chatId||
   Number(p.message_thread_id)!==threadId||
   Number(p.telegram_message_id)!==oldId||
   Number(p.management_fee_bps)!==3000||
   p.fee_policy_id!=='sticker-admin-30-20261113'||
   !p.fee_terms_accepted_at)
  throw Error('STK_REPAIR_EXISTING_POST_STATE_CHANGED');
 const sales=await pool.query('SELECT COUNT(*)::int AS n FROM videobot_sticker_paid_photo_sales WHERE product_id=$1',[pid]);
 const orders=await pool.query('SELECT COUNT(*)::int AS n FROM videobot_sticker_orders WHERE product_id=$1',[pid]);
 if(sales.rows[0].n!==0||orders.rows[0].n!==0)
  throw Error('STK_REPAIR_PURCHASES_EXIST');
 const token=readFileSync(e.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim();
 const api=createTelegramBotApi({token,fetchImpl:outgoing.fetch,timeoutMs:25000});
 const me=await api('getMe',{});
 if(me?.is_bot!==true||String(me.username||'').toLowerCase()!=='createvdobot')
  throw Error('STK_REPAIR_NOT_CREATEVDOBOT');
 const pin=JSON.parse(readFileSync('/var/lib/videobot/sticker-entry/group2373696859_thread4640.json','utf8'));
 if(pin.status!=='pinned_ack'||Number(pin.bot_id)!==me.id||
    Number(pin.chat_id)!==chatId||Number(pin.thread_id)!==threadId||
    Number(pin.message_id)===oldId)
   throw Error('STK_REPAIR_FIXED_ENTRY_PROTECTED');
 const member=await api('getChatMember',{chat_id:chatId,user_id:me.id});
 if(!['administrator','creator'].includes(member?.status))
  throw Error('STK_REPAIR_NO_BOT_TOPIC_ACCESS');
 const transactions=await api('getStarTransactions',{offset:0,limit:100});
 if(!Array.isArray(transactions?.transactions)||transactions.transactions.length===100)
  throw Error('STK_REPAIR_UNVERIFIED_STARS_HISTORY');
 if(transactions.transactions.some(tx=>JSON.stringify(tx).includes(pid)))
  throw Error('STK_REPAIR_TELEGRAM_PAYMENT_EXISTS');
 const cover=await createStickerPaidCover({
   fetchSource:createTelegramVideoFetcher({telegramApi:api,token,fetchImpl:outgoing.fetch})
 })(p);
 if(!(cover instanceof Uint8Array)||cover.byteLength<1||cover.byteLength>10000000)
  throw Error('STK_REPAIR_COVER_INVALID');
 const caption='🎨 '+p.title;
 // One Telegram operation only; no automatic retry after unknown send result.
 const sent=await api('sendPaidMedia',{
   chat_id:chatId,message_thread_id:threadId,star_count:50,
   media:[{type:'photo',media:'attach://sticker_cover'}],
   sticker_cover_bytes:cover,payload:'stkmedia_'+pid,caption
 });
 if(!Number.isSafeInteger(sent?.message_id)||sent.message_id<=0||
    sent.message_id===oldId||sent?.chat?.id!==chatId||
    sent.message_thread_id!==threadId||sent.is_topic_message!==true||
    sent.from?.id!==me.id||Number(sent.paid_media?.star_count)!==50||
    sent.paid_media?.paid_media?.length!==1||
    !['preview','photo'].includes(sent.paid_media.paid_media[0]?.type))
  throw Error('STK_REPAIR_NEW_PAID_MEDIA_UNVERIFIED');
 console.log('STK_REPAIR_NEW_PAID_MEDIA_ACK=PASS');
 console.log('STK_REPAIR_NEW_MESSAGE_ID='+sent.message_id);
 const saved=await pool.query("UPDATE videobot_sticker_topic_posts SET telegram_message_id=$2,display_text=$3,updated_at=NOW() WHERE product_id=$1 AND status='sent' AND telegram_message_id=$4 AND chat_id=$5 AND message_thread_id=$6 RETURNING telegram_message_id",[pid,sent.message_id,caption,oldId,chatId,threadId]);
 if(saved.rowCount!==1)throw Error('STK_REPAIR_NEW_MESSAGE_RECEIPT_UNCERTAIN');
 console.log('STK_REPAIR_NEW_MESSAGE_DB=PASS');
 // The original collapsed text post is removed only after the Stars photo and
 // durable new receipt have both been confirmed. Never touch the pinned entry.
 const deleted=await api('deleteMessage',{chat_id:chatId,message_id:oldId});
 if(deleted!==true)throw Error('STK_REPAIR_OLD_TEXT_POST_DELETE_UNVERIFIED');
 console.log('STK_REPAIR_OLD_TEXT_POST_REMOVED=PASS');
 console.log('STK_REPAIR_SAME_PRODUCT_SAME_TOPIC=PASS');
}finally{await outgoing.close();await pool.end();}
NODE
